if(page==='Empresas')html=title('Empresas do grupo','Cada empresa mantém seus produtos, contratos e regras de comissão.')+`<div class="rules">${allowed().map(c=>`<section class="panel"><div class="company-mark">${esc(c.name.slice(0,2).toUpperCase())} ↗</div><h2>${esc(c.name)}</h2><p>${state.products.filter(p=>p.company===c.id).length} produtos · ${state.contracts.filter(x=>x.company===c.id&&!x.archived).length} contratos</p><p>${state.products.some(p=>p.company===c.id)?'Políticas independentes por produto':'Aguardando cadastro de produtos e políticas'}</p><div class="actions">${btn('Acessar empresa',`changeCompany('${contractIdLiteral(c.id)}');go('Visão geral')`,true)}</div></section>`).join('')}</div>`;
if(page==='Contratos'&&canManage())html=title(moduleLabel('Contratos'),'Empresa, produto e versão da política vinculados a cada venda.',(canSell()?btn('+ Nova venda','newSale()'):''))+`<section class="panel"><div class="filters"><input aria-label="Buscar contrato por código ou cliente" placeholder="Buscar cliente ou código do contrato…" oninput="query=this.value;refreshContracts()"></div><div id="contractRows">${contractTable(typeof saleList==='function'?saleList(list).filter(c=>matchesContract(c,query)):list)}</div></section>`;
