function contractTable(list){return table(['Cliente / empresa','Produto','Valor','Responsáveis','Política','Ações'],list.map(c=>[`${esc(c.client)}<div class="small">${contractReference(c)} · ${esc(companyName(c.company))} · ${esc(c.reviewStatus?({draft:'Rascunho',submitted:'Em análise',returned:'Devolvida',approved:'Aprovada'}[c.reviewStatus]||c.status):c.status)}</div>`,`${esc(product(c.product)?.name)}<div class="small">${esc(c.plan)}</div>`,money(c.monthly),`${esc(userName(c.seller))}<div class="small">${esc(userName(c.dev))}</div>`,`v${c.version}`,`<div class="catalog-actions">${accessibleModules().includes('Contratos')?productAction('files','Venda e documentos',`openSalePortal(${contractIdLiteral(c.id)})`):''}${canManage('Contratos')?`${productAction('edit','Editar contrato',`editContract(${contractIdLiteral(c.id)})`)}${!c.reviewStatus||c.reviewStatus==='approved'?productAction('copy','Duplicar contrato',`duplicateContract(${contractIdLiteral(c.id)})`)+productAction(c.status==='Ativo'?'cancel':'restore',c.status==='Ativo'?'Cancelar contrato':'Reativar contrato',`confirmContractStatus(${contractIdLiteral(c.id)})`):''}${productAction('delete','Arquivar contrato',`archiveContract(${contractIdLiteral(c.id)})`)}`:''}</div>`]))}function refreshContracts(){document.getElementById('contractRows').innerHTML=contractTable(visible().filter(c=>(c.client+' '+contractCode(c)).toLowerCase().includes(query.toLowerCase())))}
function show(html,submit){let m=document.getElementById('modal');m.classList?.remove('sale-portal','settings-modal');m.innerHTML=html;m.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target;if(form.dataset.submitting)return;form.dataset.submitting='1';const buttons=form.querySelectorAll('button');const data=new FormData(form);try{const submitted=submit(data);buttons.forEach(b=>b.disabled=true);await submitted;if(typeof cloudSaving!=='undefined'&&cloudSaving)await new Promise((resolve,reject)=>cloudWaiters.push({resolve,reject}));}catch(error){toast(error.message||'Não foi possível salvar.');}finally{delete form.dataset.submitting;buttons.forEach(b=>b.disabled=false);}};m.showModal()}function actions(){return `<div class="actions">${btn('Cancelar',"document.getElementById('modal').close()",true)}<button class="btn" type="submit">Salvar</button></div>`}function field(name,label,value='',type='text',attrs=''){return `<div class="field"><label for="f_${name}">${label}</label><input id="f_${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`}function select(name,label,options,value){return `<div class="field"><label for="f_${name}">${label}</label><select id="f_${name}" name="${name}">${options.map(([id,n])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(n)}</option>`).join('')}</select></div>`}async function closeSaved(msg){try{await save();document.getElementById('modal').close();render();toast(msg);}catch(e){toast(e.message||'Não foi possível confirmar o salvamento.');}}
function editUser(id,seed){if(!isAdmin())return;let u=state.users.find(x=>x.id===id)||seed||{name:'',email:'',role:'Colaborador',companies:[],all:false,active:true};show(`<h2>${id?'Editar':'Cadastrar'} usuário</h2><p>Acesso de demonstração · nenhum convite será enviado.</p><form>${!id?`<div class="field" style="margin-top:18px"><label for="permissionSource">Copiar permissões de (opcional)</label><select id="permissionSource" onchange="applyUserPermissions(this.value)"><option value="">Definir manualmente</option>${state.users.filter(x=>x.active).map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('')}</select></div>`:''}<div class="formgrid" style="margin-top:22px">${field('name','Nome',u.name,'text','required')}${field('email','E-mail',u.email,'email')}${select('role','Perfil',['Administrador','Gestor','Colaborador'].map(x=>[x,x]),u.role)}${select('active','Status',[['yes','Ativo'],['no','Inativo']],u.active?'yes':'no')}</div><h3>Empresas autorizadas</h3><label><input type="checkbox" name="all" ${u.all?'checked':''}> Todas as empresas, incluindo futuras</label><div class="checks">${state.companies.map(c=>`<label><input name="companies" value="${contractIdLiteral(c.id)}" type="checkbox" ${u.companies.includes(c.id)?'checked':''}> ${esc(c.name)}</label>`).join('')}</div><p class="small">Administradores têm acesso integral. Colaboradores veem apenas as próprias comissões.</p>${actions()}</form>`,f=>{if(!isAdmin())return;let role=f.get('role'),active=f.get('active')==='yes',name=f.get('name').trim(),email=f.get('email').trim(),all=role==='Administrador'||f.has('all'),companies=f.getAll('companies');if(!name)return toast('Informe o nome.');if(!all&&!companies.length)return toast('Selecione ao menos uma empresa.');if(email&&state.users.some(x=>x.id!==id&&x.email.toLowerCase()===email.toLowerCase()))return toast('Este e-mail já está cadastrado.');if(id===currentUser&&(role!=='Administrador'||!active))return toast('Mantenha seu próprio acesso de administrador ativo.');let data={id:id||'u'+Date.now(),name,email,role,active,all,companies:all?[]:companies};if(id)state.users=state.users.map(x=>x.id===id?data:x);else state.users.push(data);closeSaved('Usuário salvo. Acesso disponível na simulação.');})}
function editProduct(id){if(!canManage('Produtos e regras'))return;let p=product(id);if(p&&!canAccess(p.company))return;let isNew=!p;p=p||{company:company==='all'?allowed()[0]?.id:company,name:'',type:'Recorrente',rules:{...zeroRules},version:0};if(!p.company)return toast('Nenhuma empresa autorizada.');let labels={first:'Venda · primeiro fee ou venda avulsa (%)',next:'Venda · fees seguintes (%)',setup:'Venda · implementação (%)',devFirst:'Dev · primeiro fee ou venda avulsa (%)',devSetup:'Dev · implementação (%)',months:'Último fee comissionável'};show(`<h2>${id?'Editar política':'Novo produto'}</h2><p>Percentuais exclusivos deste produto. Novas versões não alteram vendas anteriores.</p><form><div class="formgrid" style="margin-top:20px">${field('name','Nome do produto',p.name,'text','required')}${isNew?select('company','Empresa',allowed().map(c=>[c.id,c.name]),p.company):`<div class="field"><label>Empresa</label><p>${esc(companyName(p.company))}</p></div>`}${select('type','Natureza da receita',[['Recorrente','Recorrente'],['Avulsa','Avulsa']],p.type)}${select('billingMode','Duração da cobrança recorrente',[['ongoing','Enquanto o contrato estiver ativo'],['fixed','Prazo definido']],p.billingMode||'ongoing')}${field('billingMonths','Mensalidades · somente para prazo definido',p.billingMonths||12,'number','min="1" max="120" step="1"')}${field('baseMonthly','Mensalidade / venda · valor base (R$)',p.baseMonthly??'','number','min="0" step=".01"')}${field('baseSetup','Implementação · valor base (R$)',p.baseSetup??'','number','min="0" step=".01"')}${Object.keys(labels).map(k=>field(k,labels[k],p.rules[k],'number',`required min="${k==='months'?1:0}" max="${k==='months'?120:100}" step="${k==='months'?1:'.1'}"`)).join('')}</div><p>Venda avulsa gera comissão apenas no primeiro ciclo e não entra no MRR. Parceiros e outros modelos serão adicionados conforme a política de cada empresa.</p>${actions()}</form>`,f=>{if(!canManage('Produtos e regras'))return;let rules=Object.fromEntries(Object.keys(labels).map(k=>[k,Number(f.get(k))]));if(Object.entries(rules).some(([k,v])=>!Number.isFinite(v)||v<(k==='months'?1:0)||v>(k==='months'?120:100))||!Number.isInteger(rules.months))return toast('Revise os percentuais.');if(rules.setup+rules.devSetup>100||rules.first+rules.devFirst>100)return toast('A distribuição da implementação ultrapassa 100%.');let cid=id?p.company:f.get('company');if(!canAccess(cid))return;let name=f.get('name').trim();if(!name)return toast('Informe o nome.');if(id&&p.type!==f.get('type')&&state.contracts.some(c=>c.product===id))return toast('Produto com contratos: crie outro produto para mudar a natureza da receita.');const baseMonthly=f.get('baseMonthly')===''?null:Number(f.get('baseMonthly')),baseSetup=f.get('baseSetup')===''?null:Number(f.get('baseSetup'));if([baseMonthly,baseSetup].some(v=>v!==null&&(!Number.isFinite(v)||v<0)))return toast('Informe valores base válidos.');const billingMode=f.get('type')==='Avulsa'?'once':f.get('billingMode'),billingMonths=billingMode==='fixed'?Number(f.get('billingMonths')):null;if(billingMode==='fixed'&&(!Number.isInteger(billingMonths)||billingMonths<1||billingMonths>120))return toast('Informe de 1 a 120 mensalidades.');let data={...p,billingMode,billingMonths,id:id||'p'+Date.now(),company:cid,name,type:f.get('type'),baseMonthly:baseMonthly===null?null:Math.round(baseMonthly*100)/100,baseSetup:baseSetup===null?null:Math.round(baseSetup*100)/100,rules,version:p.version+1};if(id)state.products=state.products.map(x=>x.id===id?data:x);else state.products.push(data);closeSaved('Política salva para novas vendas.');});document.getElementById('f_type').onchange=configureProductBilling;document.getElementById('f_billingMode').onchange=configureProductBilling;configureProductBilling();}
function configureProductBilling(){const recurring=document.getElementById('f_type').value==='Recorrente',mode=document.getElementById('f_billingMode'),months=document.getElementById('f_billingMonths');mode.closest('.field').hidden=!recurring;months.closest('.field').hidden=!recurring||mode.value!=='fixed';months.required=recurring&&mode.value==='fixed';}
function legacyEditContract(id,seed){if(!canManage('Contratos'))return;let c=state.contracts.find(x=>x.id===id)||seed;if(c&&!canAccess(c.company))return;let options=c?[product(c.product)]:products();if(!options.length){toast('Cadastre um produto e sua política nesta empresa.');go('Produtos e regras');return}let isNew=!c;c=c||{product:options[0].id,client:'',plan:'',monthly:0,setup:0,seller:'',dev:'',start:'2026-10-15',fee:1,status:'Ativo',started:false,accepted:false};const people=state.users.filter(u=>u.active);show(`<h2>${id?'Editar':'Novo'} contrato</h2><p>${id?'A versão da política desta venda será preservada.':'A política atual do produto será guardada neste contrato.'}</p><form><div class="formgrid" style="margin-top:20px">${field('client','Cliente',c.client,'text','required')}${select('product','Produto / empresa',options.map(p=>[p.id,p.name+' · '+companyName(p.company)]),c.product)}${field('plan','Plano / descrição',c.plan)}${field('start','Data de ativação',c.start,'date','required')}${field('monthly','Mensalidade ou venda avulsa (R$)',c.monthly,'number','required min="0" step=".01"')}${field('setup','Implementação (R$)',c.setup,'number','required min="0" step=".01"')}${select('seller','Vendedor',[['','Não atribuído'],...people.map(u=>[u.id,u.name])],c.seller)}${select('dev','Desenvolvedor',[['','Não atribuído'],...people.map(u=>[u.id,u.name])],c.dev)}${field('fee','Número do fee / ciclo',c.fee,'number','required min="1" step="1"')}${select('status','Situação',[['Ativo','Ativo'],['Cancelado','Cancelado']],c.status)}</div><div class="checks"><label><input name="started" type="checkbox" ${c.started?'checked':''}> Implantação iniciada</label><label><input name="accepted" type="checkbox" ${c.accepted?'checked':''}> Aceite registrado</label></div>${actions()}</form>`,f=>{if(!canManage('Contratos'))return;const p=product(f.get('product'));if(!p||!canAccess(p.company)||(!id&&p.archived))return;if(f.has('accepted')&&!f.has('started'))return toast('Registre o início da implantação antes do aceite.');const client=f.get('client').trim(),monthly=Number(f.get('monthly')),setup=Number(f.get('setup')),fee=Number(f.get('fee'));if(!client||![monthly,setup,fee].every(Number.isFinite)||monthly<0||setup<0||fee<1||!Number.isInteger(fee))return toast('Revise os dados.');if(p.type==='Avulsa'&&fee!==1)return toast('Venda avulsa deve usar o primeiro ciclo.');let data={...c,...Object.fromEntries(f),client,monthly,setup,fee,id:id||Date.now(),company:p.company,started:f.has('started'),accepted:f.has('accepted'),paid:id?c.paid:false,rules:structuredClone(id?c.rules:p.rules),version:id?c.version:p.version};if(id)state.contracts=state.contracts.map(x=>x.id===id?data:x);else state.contracts.push(data);closeSaved('Contrato salvo com política própria.');})}
function togglePaid(id){if(!canManage())return;let c=state.contracts.find(c=>c.id===id);if(!c||!canAccess(c.company))return;if(c.status!=='Ativo')return toast('Contrato cancelado: recebimento não alterado.');c.paid=!c.paid;save();render();toast('Recebimento atualizado na simulação.')}

function duplicateProduct(id){if(!canManage('Produtos e regras'))return;const p=product(id);if(!p||p.archived||!canAccess(p.company))return;let base=p.name+' (cópia)',name=base,n=2;while(state.products.some(x=>x.company===p.company&&x.name===name))name=base+' '+n++;const copy={...structuredClone(p),id:'p'+Date.now()+'-'+Math.random().toString(36).slice(2,7),name,version:1,archived:false};state.products.push(copy);save();document.getElementById('modal').close();render();toast('Produto duplicado com política independente.');}
function deleteProduct(id){if(!canManage('Produtos e regras'))return;const p=product(id);if(!p||!canAccess(p.company))return;p.archived=true;closeSaved('Produto excluído do catálogo. Histórico preservado; restauração disponível.');}
function restoreProduct(id){if(!canManage('Produtos e regras'))return;const p=product(id);if(!p||!canAccess(p.company))return;p.archived=false;save();render();toast('Produto restaurado ao catálogo.');}

let draggedProduct=null;
function productCatalog(c){const list=products().filter(p=>p.company===c.id);return `<section class="panel" style="margin-bottom:20px"><div class="panelhead"><h2>${esc(c.name)}</h2><span class="small">${list.length} produtos · ordem personalizada</span></div><table class="product-catalog"><thead><tr><th>Ordem</th><th>Produto</th><th>Receita</th><th>Mensalidade / venda base</th><th>Implementação base</th><th>Política</th><th>Ações</th></tr></thead><tbody>${list.map((p,i)=>`<tr data-product="${esc(p.id)}" ondragover="productDragOver(event,'${actionId(p.id)}')" ondragleave="this.classList.remove('drop-target')" ondrop="productDrop(event,'${actionId(p.id)}')"><td><div class="sort-controls"><button class="drag-handle" draggable="true" ondragstart="productDragStart(event,'${actionId(p.id)}')" ondragend="productDragEnd()" onkeydown="productKey(event,'${actionId(p.id)}')" aria-label="Arrastar ${esc(p.name)}" title="Arraste para ordenar ou use as setas do teclado">⠿</button><span class="small">${i+1}</span><button class="order-btn" ${i===0?'disabled':''} onclick="moveProduct('${actionId(p.id)}',-1)" aria-label="Mover ${esc(p.name)} para cima">↑</button><button class="order-btn" ${i===list.length-1?'disabled':''} onclick="moveProduct('${actionId(p.id)}',1)" aria-label="Mover ${esc(p.name)} para baixo">↓</button></div></td><td><strong>${esc(p.name)}</strong></td><td>${esc(p.type)}</td><td class="base-prices"><strong>${p.baseMonthly==null?'Não definido':money(p.baseMonthly)}</strong></td><td class="base-prices"><strong>${p.baseSetup==null?'Não definido':money(p.baseSetup)}</strong></td><td>Versão ${p.version}<div class="small">Venda ${p.rules.first}% / ${p.rules.next}%</div></td><td><div class="catalog-actions">${productAction('edit','Editar política',`editProduct('${actionId(p.id)}')`)}${productAction('copy','Duplicar produto',`duplicateProduct('${actionId(p.id)}')`)}${productAction('delete','Excluir produto',`deleteProduct('${actionId(p.id)}')`)}</div></td></tr>`).join('')}</tbody></table></section>`}
function reorderProduct(id,target){if(!canManage('Produtos e regras')||id===target)return false;const p=product(id),t=product(target);if(!p||!t||p.archived||t.archived||p.company!==t.company||!canAccess(p.company))return false;let list=state.products.filter(x=>x.company===p.company&&!x.archived);let from=list.findIndex(x=>x.id===id),to=list.findIndex(x=>x.id===target);list.splice(to,0,list.splice(from,1)[0]);let i=0;state.products=state.products.map(x=>x.company===p.company&&!x.archived?list[i++]:x);save();render();return true;}
function moveProduct(id,delta){const p=product(id);if(!p)return;const list=products().filter(x=>x.company===p.company),i=list.findIndex(x=>x.id===id),target=list[i+delta];if(target&&reorderProduct(id,target.id)){toast('Ordem dos produtos salva.');document.querySelector(`[data-product="${id}"] .drag-handle`)?.focus();}}
function productKey(e,id){if(e.key==='ArrowUp'||e.key==='ArrowDown'){e.preventDefault();moveProduct(id,e.key==='ArrowUp'?-1:1);}}
function productDragStart(e,id){if(!canManage()){e.preventDefault();return}draggedProduct=id;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',id);e.target.closest('tr').classList.add('dragging');}
function productDragOver(e,id){const p=product(draggedProduct),t=product(id);if(p&&t&&p.company===t.company&&id!==draggedProduct){e.preventDefault();e.dataTransfer.dropEffect='move';e.currentTarget.classList.add('drop-target');}}
function productDrop(e,id){e.preventDefault();if(reorderProduct(draggedProduct,id))toast('Ordem dos produtos salva.');productDragEnd();}
function productDragEnd(){draggedProduct=null;document.querySelectorAll('.drop-target,.dragging').forEach(el=>el.classList.remove('drop-target','dragging'));}


function productAction(icon,label,action){const paths={files:'<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6M8 13h8M8 17h6"/>',check:'<path d="m5 12 4 4L19 6"/>',cancel:'<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>',restore:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',power:'<path d="M12 3v9M6 5a9 9 0 1 0 12 0"/>',edit:'<path d="m15 5 4 4M4 20l4-1 12-12a2.8 2.8 0 0 0-4-4L4 15z"/>',copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M15 8V4a1 1 0 0 0-1-1H4a1 1 0 0 0-1 1v10a1 1 0 0 0 1 1h4"/>',delete:'<path d="M3 6h18M9 6V3h6v3M5 6l1 14h12l1-14M10 10v6M14 10v6"/>'};return `<button type="button" class="icon-action ${icon==='delete'||icon==='cancel'?'danger':''}" aria-label="${label}" data-tooltip="${label}" onclick="${esc(action)}"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[icon]}</svg></button>`;}

function legacyDuplicateContract(id){if(!canManage())return;const c=state.contracts.find(x=>x.id===id);if(!c||!canAccess(c.company))return;if(product(c.product)?.archived)return toast('Restaure o produto antes de criar outra venda.');const seed={...structuredClone(c),client:c.client+' (cópia)',status:'Ativo',paid:false,fee:1,started:false,accepted:false};delete seed.id;editContract(undefined,seed);toast('Revise a nova venda. Recebimentos e etapas foram zerados.');}
function confirmContractStatus(id){if(!canManage('Contratos'))return;const c=state.contracts.find(x=>x.id===id);if(!c||!canAccess(c.company))return;const cancel=c.status==='Ativo';show(`<h2>${cancel?'Cancelar':'Reativar'} contrato</h2><p>${esc(c.client)} · ${esc(companyName(c.company))}</p><div class="notice">${cancel?'O contrato deixará de compor o MRR ativo e as comissões liberáveis. Os registros serão preservados e poderão ser reativados.':'O contrato voltará à base ativa. Recebimentos e etapas já registrados serão preservados.'}</div><form><div class="actions"><button type="button" class="btn secondary" onclick="document.getElementById('modal').close()">Voltar</button><button class="btn">Confirmar ${cancel?'cancelamento':'reativação'}</button></div></form>`,()=>{if(!canManage('Contratos')||!canAccess(c.company))return;c.status=cancel?'Cancelado':'Ativo';c.cancelledAt=cancel?localToday():null;closeSaved(cancel?'Contrato cancelado. Histórico preservado.':'Contrato reativado.');});}
function copyUserPermissions(id){if(!isAdmin())return;const u=state.users.find(x=>x.id===id);if(!u)return;editUser(undefined,{name:'',email:'',role:u.role,all:u.all,companies:[...u.companies],active:true});document.getElementById('permissionSource').value=id;}
function applyUserPermissions(id){if(!isAdmin())return;const u=state.users.find(x=>x.id===id);if(!u)return;const form=document.getElementById('modal').querySelector('form');form.elements.namedItem('role').value=u.role;form.elements.namedItem('all').checked=u.all;form.querySelectorAll('input[name="companies"]').forEach(el=>el.checked=u.companies.includes(el.value));}
function toggleUserActive(id){if(!isAdmin())return;const u=state.users.find(x=>x.id===id);if(!u||u.id===currentUser)return toast('Seu próprio acesso deve permanecer ativo.');u.active=!u.active;closeSaved(u.active?'Usuário ativado.':'Usuário desativado. Histórico preservado.');}

if(!state.goals){state.goals=[];save();}
let goalYear='all';
function nextPeriod(period){let [year,month]=period.split('-').map(Number);if(month===12){year++;month=1}else month++;return year+'-'+String(month).padStart(2,'0');}
function periodLabel(period){const [y,m]=period.split('-').map(Number);return periodFormat.format(new Date(Date.UTC(y,m-1,1)));}
function scopedGoals(){return state.goals.filter(g=>canAccess(g.company)&&(company==='all'||company===g.company));}
function renderGoals(){const all=scopedGoals(),years=[...new Set(all.map(g=>g.period.slice(0,4)))].sort();const list=all.filter(g=>goalYear==='all'||g.period.startsWith(goalYear)).sort((a,b)=>a.period.localeCompare(b.period)||companyName(a.company).localeCompare(companyName(b.company)));const val=(v,currency=false)=>v===null||v===undefined?'—':currency?money(v):v;const achievement=(actual,target)=>actual==null||target==null||target<=0?'—':Math.round(actual/target*100)+'%';return title('Metas por empresa','Planeje cada mês e ano com metas próprias para cada empresa.',btn('+ Adicionar mês','editGoal()'))+`<div class="notice">Metas são definidas por empresa e mês. O realizado pode ser manual ou calculado pelas novas vendas, conforme a opção em “Origem do realizado”. Os meses importados da planilha são referências, inclusive valores futuros, e precisam de conferência.</div><div class="filters"><label for="goalYear">Ano</label><select id="goalYear" onchange="goalYear=this.value;render()"><option value="all">Todos os anos</option>${years.map(y=>`<option ${goalYear===y?'selected':''}>${y}</option>`).join('')}</select></div>`+(list.length?`<section class="panel">${table(['Mês / empresa','Novos clientes','Faturamento','MRR ao fim do mês','Ações'],list.map(g=>[`<strong>${esc(periodLabel(g.period))}</strong><div class="small">${esc(companyName(g.company))}</div>${g.source?'<div class="small">Referência importada</div>':''}`,`Meta: ${val(g.clients)}<div class="small">Realizado: ${val(g.actualClients)} · ${achievement(g.actualClients,g.clients)}</div>`,`Meta: ${val(g.revenue,true)}<div class="small">Realizado: ${val(g.actualRevenue,true)} · ${achievement(g.actualRevenue,g.revenue)}</div>`,`Meta: ${val(g.mrr,true)}<div class="small">Realizado: ${val(g.actualMrr,true)} · ${achievement(g.actualMrr,g.mrr)}</div>`,`<div class="catalog-actions">${productAction('edit','Editar metas',`editGoal('${g.id}')`)}${productAction('copy','Copiar para outro mês',`copyGoal('${g.id}')`)}</div>`]))}</section>`:empty('Nenhuma meta neste período','Adicione um mês para a empresa desejada. Você pode escolher qualquer mês e ano.'))+`<p class="small" style="margin-top:15px">Faturamento: valor do mês, incluindo receitas avulsas. MRR: receita recorrente mensal ao fim do período; não deve ser somado entre meses. Campos vazios significam não informado.</p>`;}
function editGoal(id,seed){if(!canManage('Metas'))return;let g=state.goals.find(g=>g.id===id)||seed;if(g&&!canAccess(g.company))return;let cid=company==='all'?allowed()[0]?.id:company;if(!cid)return toast('Nenhuma empresa autorizada.');if(!g){let latest=state.goals.filter(g=>g.company===cid).map(g=>g.period).sort().at(-1);g={company:cid,period:latest?nextPeriod(latest):new Intl.DateTimeFormat('sv-SE',{timeZone:'America/Sao_Paulo',year:'numeric',month:'2-digit'}).format(new Date()),autoActual:true,clients:null,revenue:null,mrr:null,actualClients:null,actualRevenue:null,actualMrr:null};}const fields=[['clients','Meta · novos clientes'],['revenue','Meta · faturamento (R$)'],['mrr','Meta · MRR (R$)'],['actualClients','Realizado · novos clientes'],['actualRevenue','Realizado · faturamento (R$)'],['actualMrr','Realizado · MRR (R$)']];show(`<h2>${id?'Editar metas':'Adicionar mês'}</h2><p>Metas exclusivas por empresa e período. Deixe vazio o que ainda não foi definido.</p><form><div class="formgrid" style="margin-top:20px">${select('company','Empresa',allowed().map(c=>[c.id,c.name]),g.company)}${select('goalMonth','Mês',Array.from({length:12},(_,n)=>[String(n+1).padStart(2,'0'),new Intl.DateTimeFormat('pt-BR',{month:'long',timeZone:'UTC'}).format(new Date(Date.UTC(2026,n,1)))]),g.period.slice(5,7))}${select('goalYearInput','Ano',goalEditorYears(g.period.slice(0,4)).map(y=>[y,y]),g.period.slice(0,4))}<div class="field"><label>Outros anos</label><div class="catalog-actions">${btn('Ano anterior',"extendGoalYear(-1)",true)}${btn('Próximo ano',"extendGoalYear(1)",true)}</div></div>${select('actualMode','Origem do realizado',[['auto','Automático'],['manual','Manual']],g.autoActual?'auto':'manual')}${fields.map(([k,l])=>field(k,l,g[k]??'','number',`min="0" step="${k.toLowerCase().includes('clients')?1:'.01'}"`)).join('')}</div><p class="small" id="goalActualHelp"></p><p class="small">Novos clientes: primeira venda aprovada no mês. Faturamento realizado: recebimentos do mês. MRR: recorrência ativa ao fim do mês. Copiar metas não copia os valores realizados.</p>${actions()}</form>`,f=>{if(!canManage('Metas'))return;const cid=f.get('company'),period=f.get('goalYearInput')+'-'+f.get('goalMonth'),autoActual=f.get('actualMode')==='auto';if(!canAccess(cid)||!/^\d{4}-(0[1-9]|1[0-2])$/.test(period)||Number(period.slice(0,4))<1)return toast('Informe uma empresa e um mês válidos.');if(state.goals.some(x=>x.id!==id&&x.company===cid&&x.period===period))return toast('Esta empresa já possui metas neste mês. Edite o registro existente.');const values={};for(const [k]of fields){const raw=autoActual&&k.startsWith('actual')?document.getElementById('f_'+k).dataset.manualValue:f.get(k);values[k]=raw===''?null:Number(raw);if(values[k]!==null&&(!Number.isFinite(values[k])||values[k]<0||(k.toLowerCase().includes('clients')&&!Number.isInteger(values[k]))))return toast('Informe valores positivos e quantidades inteiras de clientes.');}const data={...g,...values,autoActual,id:id||'goal-'+Date.now(),company:cid,period};if(id)state.goals=state.goals.map(x=>x.id===id?data:x);else state.goals.push(data);goalYear=period.slice(0,4);closeSaved('Metas salvas para '+companyName(cid)+' · '+periodLabel(period)+'.');});for(const key of ['company','goalMonth','goalYearInput','actualMode'])document.getElementById('f_'+key).onchange=refreshGoalActuals;refreshGoalActuals();}
function copyGoal(id){if(!canManage('Metas'))return;const g=state.goals.find(g=>g.id===id);if(!g||!canAccess(g.company))return;editGoal(undefined,{company:g.company,period:nextPeriod(g.period),clients:g.clients,revenue:g.revenue,mrr:g.mrr,actualClients:null,actualRevenue:null,actualMrr:null,autoActual:!!g.autoActual});}

function goalEditorYears(selected){const current=new Date().getFullYear(),years=new Set(Array.from({length:11},(_,n)=>String(current-5+n)));years.add(String(selected));for(const g of state.goals)years.add(g.period.slice(0,4));for(const c of state.contracts)if(c.start)years.add(c.start.slice(0,4));return [...years].filter(y=>/^\d{4}$/.test(y)&&Number(y)>0).sort();}
function extendGoalYear(direction){const input=document.getElementById('f_goalYearInput'),years=Array.from(input.options).map(o=>Number(o.value)),year=Number(input.value)+direction;if(year<1||year>9999)return;const value=String(year).padStart(4,'0');if(!years.includes(year)){const option=document.createElement('option');option.value=value;option.textContent=value;if(direction<0)input.prepend(option);else input.append(option);}input.value=value;refreshGoalActuals();}
function refreshGoalActuals(){const automatic=document.getElementById('f_actualMode').value==='auto',g={company:document.getElementById('f_company').value,period:document.getElementById('f_goalYearInput').value+'-'+document.getElementById('f_goalMonth').value},actual=automatic?goalActualFromSales(g):{};for(const key of ['actualClients','actualRevenue','actualMrr']){const input=document.getElementById('f_'+key);if(input.dataset.actualMode!=='auto')input.dataset.manualValue=input.value;input.readOnly=automatic;input.value=automatic?actual[key]:input.dataset.manualValue||'';input.dataset.actualMode=automatic?'auto':'manual';}document.getElementById('goalActualHelp').textContent=automatic?'Realizado calculado automaticamente para a empresa, mês e ano selecionados. Não precisa preencher esses campos.':'Realizado manual: use para referências históricas ou períodos sem lançamentos na plataforma.';}
